// A 42-limb divisor with a 63-limb dividend sits above both
// divide-and-conquer gates, yet must still constant-evaluate:
// divide_dispatch routes constant evaluation to the schoolbook kernel.
// a = b * 2^1400 + r with r < b, so q and r are known exactly.
consteval bool ce_dc_sized_division() {
    const big_int b = (big_int{1} << 2625) + big_int{987654321};
    const big_int r = (big_int{1} << 1399) + big_int{12345};
    const big_int a = (b << 1400) + r;
    return (a / b) == (big_int{1} << 1400) && (a % b) == r;
}
static_assert(ce_dc_sized_division());

